mapper.select:
select p.id, p.name, p.ad_key AS adKey, p.description, p.width, p.height, p.sort, p.status, p.create_time AS createTime, p.update_time AS updateTime, (select count(*) from fly_ad a where a.position_id = p.id) AS adCount from fly_ad_position p
and (p.name like concat('%', #{keyword}, '%') or p.ad_key like concat('%', #{keyword}, '%'))
order by p.sort, p.id limit #{offset}, #{rows}

select count(*)
from fly_ad_position
where ad_key = #{adKey}

    and id != #{excludeId}

mapper.update:
update fly_ad_position
name = #{name}, description = #{description}, width = #{width}, height = #{height}, sort = #{sort}, status = #{status}, update_time = now()
where id = #{id}

mapper.select:
select count(*)
from fly_ad
where position_id = #{positionId}
